content.arguments:
{"command":"$dir='./'
if(-not (Test-Path $dir)){ "NODIR=$dir"; exit }
Get-ChildItem -Path $dir -Recurse -File | Sort-Object FullName | ForEach-Object {
  $f=$_.FullName
  $bytes=[System.IO.File]::ReadAllBytes($f)
  $total=$bytes.Length
  $totalHash=(Get-FileHash -Algorithm SHA256 $f).Hash.Substring(0,12)
  $text=[System.IO.File]::ReadAllText($f)
  $rel=$f.Replace($dir+'\','')
  $i=$text.LastIndexOf('EVIDENCE:')
  if($i -lt 0){ "$rel | $total | $totalHash | NO_EVIDENCE_LINE"; return }
  $claimLine=($text.Substring($i) -split "`r?`n")[0]
  $body=$text.Substring(0,$i)
  $body=$body -replace '[\r\n]+$',''
  $bb=[System.Text.Encoding]::UTF8.GetByteCount($body)
  $sha=[System.Security.Cryptography.SHA256]::Create()
  $bh=(($sha.ComputeHash([System.Text.Encoding]::UTF8.GetBytes($body)) | ForEach-Object { $_.ToString('x2') }) -join '').Substring(0,12).ToUpper()
  $parts=$claimLine -split '\|'
  $cB=$null; $cH=$null
  if($parts.Length -ge 3){ $cB=$parts[$parts.Length-2]; $cH=$parts[$parts.Length-1] }
  $bOK='na'; if($cB -eq "$bb"){ $bOK='BYTES_OK' } elseif($cB){ $bOK="BYTES_DIFF(claim=$cB,body=$bb)" }
  $hOK='na'; if($cH -eq "$bh"){ $hOK='HASH_OK' } elseif($cH){ $hOK="HASH_DIFF(claim=$cH,body=$bh)" }
  "$rel | total=$total | totalSha=$totalHash | $bOK | $hOK"
}","description":"核验研究目录各文件确定量"}

