content.arguments:
{"command":"$dir='./'
Get-ChildItem -Path $dir -File -Filter *.md | Sort-Object Name | ForEach-Object {
  $f=$_.FullName; $b=[System.IO.File]::ReadAllBytes($f)
  "{0} | {1} B | {2}" -f $_.Name, $b.Length, (Get-FileHash -Algorithm SHA256 $f).Hash.Substring(0,12)
}
"---- chars ----"
Get-ChildItem -Path (Join-Path $dir 'chars') -File | Sort-Object Name | ForEach-Object {
  $f=$_.FullName; $b=[System.IO.File]::ReadAllBytes($f)
  "{0} | {1} B | {2}" -f $_.Name, $b.Length, (Get-FileHash -Algorithm SHA256 $f).Hash.Substring(0,12)
}
"---- json-parse ----"
Get-ChildItem -Path (Join-Path $dir 'chars') -File -Filter *.json | ForEach-Object {
  $lines=[System.IO.File]::ReadAllLines($_.FullName)
  $end=$lines.Length-1
  while($end -ge 0 -and $lines[$end].Trim() -eq ''){$end--}
  if($end -ge 0 -and $lines[$end].StartsWith('EVIDENCE:')){$end--}
  $body=($lines[0..$end] -join "`n")
  try { $o=$body | ConvertFrom-Json; "{0} JSON_OK changes={1}" -f $_.Name, $o.changes.Count } catch { "{0} JSON_FAIL {1}" -f $_.Name, $_.Exception.Message }
}","description":"核验全部产出文件与JSON可解析性"}

